import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  interpolateColors,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');
const loadInter = makeLoadFont('Inter');

// Module-level font loading — delayRender/continueRender handled internally by loadFont()
const { fontFamily: spaceGroteskFamily } = loadSpaceGrotesk();
const { fontFamily: interFamily } = loadInter();



export type ConformityAnimationProps = Record<string, any>;

const Seat: React.FC<{
  colorBack: string;
  colorCushion: string;
  colorArm: string;
  shadowColor: string;
  specialProgress: number;
}> = ({ colorBack, colorCushion, colorArm, shadowColor, specialProgress }) => {
  const backRx = interpolate(specialProgress, [0, 1], [6, 14]);
  const cushionRx = interpolate(specialProgress, [0, 1], [5, 12]);

  return (
    <svg
      viewBox="0 0 120 120"
      style={{
        width: "100%",
        height: "100%",
        overflow: "visible",
        filter: `drop-shadow(0px ${4 + specialProgress * 6}px ${6 + specialProgress * 8}px ${shadowColor})`,
        transition: "none",
      }}
    >
      {/* Chair stand/legs */}
      <path
        d="M 40 85 L 30 114 M 80 85 L 90 114"
        stroke={colorArm}
        strokeWidth="6.5"
        strokeLinecap="round"
        opacity={0.85}
      />

      {/* Chair Backrest */}
      <rect
        x="20"
        y="12"
        width="80"
        height="64"
        rx={backRx}
        fill={colorBack}
        stroke="rgba(0, 0, 0, 0.2)"
        strokeWidth="1.5"
      />
      {/* Stylized premium vertical crease */}
      <path
        d="M 60 18 L 60 70"
        stroke="rgba(0, 0, 0, 0.15)"
        strokeWidth="4"
        strokeLinecap="round"
      />

      {/* Cushion */}
      <rect
        x="14"
        y="58"
        width="92"
        height="32"
        rx={cushionRx}
        fill={colorCushion}
        stroke="rgba(0, 0, 0, 0.22)"
        strokeWidth="1.5"
      />
      {/* Inner highlight ring */}
      <rect
        x="24"
        y="64"
        width="72"
        height="18"
        rx={Math.max(1, cushionRx - 2)}
        fill="none"
        stroke="rgba(255, 255, 255, 0.08)"
        strokeWidth="2"
      />

      {/* Left Armrest */}
      <rect
        x="7"
        y="42"
        width="12"
        height="40"
        rx="4"
        fill={colorArm}
        stroke="rgba(0, 0, 0, 0.25)"
        strokeWidth="1"
      />

      {/* Right Armrest */}
      <rect
        x="101"
        y="42"
        width="12"
        height="40"
        rx="4"
        fill={colorArm}
        stroke="rgba(0, 0, 0, 0.25)"
        strokeWidth="1"
      />
    </svg>
  );
};

export const ConformityAnimation: React.FC<ConformityAnimationProps> = ({
  backgroundColor = "#0a0b0d",
  transparentBackground = false,
  durationInSeconds = 8,
  crowdSeatColor = "#3d3e42",
  crowdSeatCushionColor = "#505257",
  leatherSeatColor = "#ae5f25",
  leatherSeatCushionColor = "#c77c38",
  spotlightColor = "#cca36d",
  headline = "STAND OUT",
  caption1 = "Lost in a sea of identical choices.",
  caption2 = "One decided to break away...",
  caption3 = "To create a space entirely its own.",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Layout parameters
  const numRows = 14;
  const numCols = 10;
  const specialRow = 13; // Front-most row
  const specialCol = 8;  // Near the right edge

  // Timing bounds based on actual configuration
  const startFrame = fps * 2; // Starts separating at 2 seconds
  const endFrame = fps * (durationInSeconds - 2.2); // Finishes transition before end

  // Overall progress of separation
  const travelProgress = interpolate(frame, [startFrame, endFrame], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.28, 0.11, 0.22, 1.0),
  });

  // Calculate coordinates and scale for any seat in the grid dynamically
  const getGridPosition = (row: number, col: number, compressVal: number) => {
    // Normal progress down the theater rows (0 is far, 1 is close)
    const progressY = row / (numRows - 1);

    // As compression increases, rows pull even closer vertically
    const verticalCompression = interpolate(compressVal, [0, 1], [1.0, 0.86]);
    const verticalStart = height * 0.12;
    const verticalSpan = height * 0.46 * verticalCompression;
    const y = verticalStart + progressY * verticalSpan;

    // Classic perspective width effect (row widths grow as they come closer)
    const baseRowWidth = width * interpolate(progressY, [0, 1], [0.72, 1.05]);
    // As compression increases, columns tighten together horizontally
    const horizontalCompression = interpolate(compressVal, [0, 1], [1.0, 0.82]);
    const rowWidth = baseRowWidth * horizontalCompression;

    const colProgress = col / (numCols - 1) - 0.5; // from -0.5 to 0.5
    const x = width * 0.5 + colProgress * rowWidth;

    // Scale is smaller in back rows, larger in front rows
    const baseScale = interpolate(progressY, [0, 1], [0.38, 0.88]);
    // As compression hits, other seats shrink in size
    const scale = baseScale * interpolate(compressVal, [0, 1], [1.0, 0.84]);

    return { x, y, scale };
  };

  // Build static seat grid list (excluding the special separating seat)
  const gridSeats = React.useMemo(() => {
    const list = [];
    for (let r = 0; r < numRows; r++) {
      for (let c = 0; c < numCols; c++) {
        if (r === specialRow && c === specialCol) {
          continue;
        }
        list.push({ row: r, col: c });
      }
    }
    return list;
  }, [numRows, numCols, specialRow, specialCol]);

  // Compute position for the special seat
  const startPos = getGridPosition(specialRow, specialCol, 0);
  const endX = width * 0.5;
  const endY = height * 0.76;

  const specialX = interpolate(travelProgress, [0, 1], [startPos.x, endX]);
  const specialY = interpolate(travelProgress, [0, 1], [startPos.y, endY]);

  // Scale up special seat as it separates
  const specialScale = interpolate(travelProgress, [0, 1], [startPos.scale, 1.55]);

  // Color transitions for the morphing seat
  const currentSeatColor = interpolateColors(travelProgress, [0, 1], [crowdSeatColor, leatherSeatColor]);
  const currentCushionColor = interpolateColors(travelProgress, [0, 1], [crowdSeatCushionColor, leatherSeatCushionColor]);
  const currentArmColor = interpolateColors(travelProgress, [0, 1], ["#222326", "#733a17"]);
  const currentShadowColor = interpolateColors(travelProgress, [0, 1], ["rgba(0,0,0,0.4)", "rgba(122,58,23,0.5)"]);

  // Spotlight underneath the final position
  const spotlightOpacity = interpolate(travelProgress, [0, 1], [0, 0.8], {
    extrapolateRight: "clamp",
  });

  // Timing milestones for caption cards
  const cap1End = startFrame - 5;
  const cap2Start = startFrame + 10;
  const cap2End = endFrame - 15;
  const cap3Start = endFrame - 5;

  // Cinematic caption text opacity fades
  const opCaption1 = interpolate(frame, [5, 20, cap1End - 10, cap1End], [0, 1, 1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const opCaption2 = interpolate(frame, [cap2Start, cap2Start + 15, cap2End - 15, cap2End], [0, 1, 1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const opCaption3 = interpolate(frame, [cap3Start, cap3Start + 18], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Tiny cinematic upward drift for typography
  const yCaption1 = interpolate(frame, [0, cap1End], [10, -10], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const yCaption2 = interpolate(frame, [cap2Start, cap2End], [10, -10], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const yCaption3 = interpolate(frame, [cap3Start, fps * durationInSeconds], [10, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  const headlineOpacity = interpolate(frame, [30, 60], [0, 0.85], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const headlineLetterSpacing = interpolate(frame, [30, 120], [4, 9], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  const resolvedBgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  return (
    <AbsoluteFill style={{ backgroundColor: resolvedBgColor, overflow: "hidden" }}>
      {/* Background radial highlight */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: `radial-gradient(circle at 50% 45%, #181a20 0%, ${backgroundColor} 80%)`,
          transition: "none",
        }}
      />

      {/* Grid of identical remaining seats */}
      <div style={{ position: "absolute", inset: 0, transition: "none" }}>
        {gridSeats.map(({ row, col }) => {
          const { x, y, scale } = getGridPosition(row, col, travelProgress);
          const sWidth = 72 * scale;
          const sHeight = 72 * scale;

          return (
            <div
              key={`${row}-${col}`}
              style={{
                position: "absolute",
                left: x - sWidth / 2,
                top: y - sHeight / 2,
                width: sWidth,
                height: sHeight,
                zIndex: row,
                transition: "none",
              }}
            >
              <Seat
                colorBack={crowdSeatColor}
                colorCushion={crowdSeatCushionColor}
                colorArm="#222326"
                shadowColor="rgba(0,0,0,0.4)"
                specialProgress={0}
              />
            </div>
          );
        })}
      </div>

      {/* Golden Warm Spotlight under the separating seat */}
      <div
        style={{
          position: "absolute",
          left: endX - 250,
          top: endY - 140,
          width: 500,
          height: 360,
          background: `radial-gradient(ellipse, ${spotlightColor}40 0%, ${spotlightColor}10 40%, transparent 70%)`,
          opacity: spotlightOpacity,
          transform: "scaleY(0.55)",
          pointerEvents: "none",
          transition: "none",
        }}
      />

      {/* The Separating / Morphing Seat */}
      <div
        style={{
          position: "absolute",
          left: specialX - (72 * specialScale) / 2,
          top: specialY - (72 * specialScale) / 2,
          width: 72 * specialScale,
          height: 72 * specialScale,
          zIndex: 99,
          transition: "none",
        }}
      >
        <Seat
          colorBack={currentSeatColor}
          colorCushion={currentCushionColor}
          colorArm={currentArmColor}
          shadowColor={currentShadowColor}
          specialProgress={travelProgress}
        />
      </div>

      {/* Cinematic Vignette */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: "radial-gradient(circle, transparent 35%, rgba(0, 0, 0, 0.7) 100%)",
          pointerEvents: "none",
          transition: "none",
        }}
      />

      {/* Headline Header */}
      <div
        style={{
          position: "absolute",
          top: height * 0.08,
          width: "100%",
          display: "flex",
          justifyContent: "center",
          opacity: headlineOpacity,
          fontFamily: spaceGroteskFamily,
          transition: "none",
        }}
      >
        <h1
          style={{
            color: "#ffffff",
            fontSize: "2.3rem",
            fontWeight: 700,
            letterSpacing: `${headlineLetterSpacing}px`,
            margin: 0,
            textShadow: "0 2px 10px rgba(0,0,0,0.5)",
            transition: "none",
          }}
        >
          {headline}
        </h1>
      </div>

      {/* Story Caption Cards Container */}
      <div
        style={{
          position: "absolute",
          bottom: height * 0.12,
          width: "100%",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          fontFamily: interFamily,
          transition: "none",
        }}
      >
        {/* Caption 1 */}
        {opCaption1 > 0 && (
          <div
            style={{
              position: "absolute",
              opacity: opCaption1,
              transform: `translateY(${yCaption1}px)`,
              textAlign: "center",
              paddingLeft: "30px",
              paddingRight: "30px",
              maxWidth: "80%",
              transition: "none",
            }}
          >
            <p
              style={{
                color: "#e2e8f0",
                fontSize: "1.25rem",
                lineHeight: 1.6,
                fontWeight: 300,
                margin: 0,
                textShadow: "0 2px 8px rgba(0,0,0,0.6)",
                transition: "none",
              }}
            >
              {caption1}
            </p>
          </div>
        )}

        {/* Caption 2 */}
        {opCaption2 > 0 && (
          <div
            style={{
              position: "absolute",
              opacity: opCaption2,
              transform: `translateY(${yCaption2}px)`,
              textAlign: "center",
              paddingLeft: "30px",
              paddingRight: "30px",
              maxWidth: "80%",
              transition: "none",
            }}
          >
            <p
              style={{
                color: "#f1f5f9",
                fontSize: "1.25rem",
                lineHeight: 1.6,
                fontWeight: 300,
                margin: 0,
                textShadow: "0 2px 8px rgba(0,0,0,0.6)",
                transition: "none",
              }}
            >
              {caption2}
            </p>
          </div>
        )}

        {/* Caption 3 */}
        {opCaption3 > 0 && (
          <div
            style={{
              position: "absolute",
              opacity: opCaption3,
              transform: `translateY(${yCaption3}px)`,
              textAlign: "center",
              paddingLeft: "30px",
              paddingRight: "30px",
              maxWidth: "80%",
              transition: "none",
            }}
          >
            <p
              style={{
                color: "#cca36d",
                fontSize: "1.35rem",
                lineHeight: 1.6,
                fontWeight: 400,
                margin: 0,
                textShadow: "0 2px 12px rgba(0,0,0,0.8)",
                transition: "none",
              }}
            >
              {caption3}
            </p>
          </div>
        )}
      </div>
    </AbsoluteFill>
  );
};

export default ConformityAnimation;